arguments.file_text:
namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe
            {
                Id = 1,
                Title = "Classic Pancakes",
                Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
                Ingredients = new List<string> { "1 cup flour", "2 tbsp sugar", "1 egg", "1 cup milk", "2 tbsp melted butter", "1 tsp baking powder" },
                Steps = new List<string> { "Mix dry ingredients in a bowl.", "Whisk egg, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Pour batter onto a hot greased griddle.", "Flip when bubbles form on the surface and cook until golden." },
                TotalRatings = 12,
                RatingSum = 50
            },
            new Recipe
            {
                Id = 2,
                Title = "Avocado Toast",
                Category = "Breakfast",
                Description = "Simple, healthy, and delicious avocado toast with a hint of lemon.",
                Ingredients = new List<string> { "2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes" },
                Steps = new List<string> { "Toast the bread until golden and crispy.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread avocado mixture on the toast.", "Sprinkle with red pepper flakes and serve." },
                TotalRatings = 8,
                RatingSum = 35
            },
            new Recipe
            {
                Id = 3,
                Title = "Spaghetti Bolognese",
                Category = "Dinner",
                Description = "A rich and hearty meat sauce served over perfectly cooked pasta.",
                Ingredients = new List<string> { "400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g canned tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper" },
                Steps = new List<string> { "Cook spaghetti according to package directions.", "Brown the ground beef in a large pan.", "Add onion and garlic, cook until softened.", "Stir in tomatoes, tomato paste, and oregano.", "Simmer for 20 minutes, season to taste.", "Serve sauce over drained spaghetti." },
                TotalRatings = 15,
                RatingSum = 68
            },
            new Recipe
            {
                Id = 4,
                Title = "Grilled Chicken Tacos",
                Category = "Dinner",
                Description = "Zesty grilled chicken tacos with fresh salsa and creamy guacamole.",
                Ingredients = new List<string> { "500g chicken breast", "8 small tortillas", "1 lime", "1 tsp cumin", "1 tsp chili powder", "Fresh cilantro", "Salsa", "Guacamole" },
                Steps = new List<string> { "Season chicken with cumin, chili powder, salt, and lime juice.", "Grill chicken until cooked through, about 6 minutes per side.", "Slice chicken into strips.", "Warm tortillas on the grill.", "Assemble tacos with chicken, salsa, guacamole, and cilantro." },
                TotalRatings = 10,
                RatingSum = 44
            },
            new Recipe
            {
                Id = 5,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                Description = "Decadent individual chocolate cakes with a molten center.",
                Ingredients = new List<string> { "200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "50g sugar", "2 tbsp flour" },
                Steps = new List<string> { "Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into greased ramekins.", "Bake for 12 minutes until edges are set but center is soft.", "Invert onto plates and serve immediately." },
                TotalRatings = 20,
                RatingSum = 94
            },
            new Recipe
            {
                Id = 6,
                Title = "Strawberry Cheesecake",
                Category = "Desserts",
                Description = "Creamy New York-style cheesecake topped with fresh strawberries.",
                Ingredients = new List<string> { "200g graham crackers", "80g melted butter", "600g cream cheese", "150g sugar", "3 eggs", "1 tsp vanilla extract", "Fresh strawberries" },
                Steps = new List<string> { "Crush graham crackers and mix with melted butter.", "Press crust into a springform pan.", "Beat cream cheese and sugar until smooth.", "Add eggs one at a time, then vanilla.", "Pour filling over crust.", "Bake at 160°C (325°F) for 50 minutes.", "Cool completely, then top with fresh strawberries." },
                TotalRatings = 14,
                RatingSum = 62
            }
        };
        _nextId = 7;
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1) stars = 1;
        if (stars > 5) stars = 5;

        var recipe = GetRecipeById(recipeId);
        if (recipe != null)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }
}

