@page "/categories/{CategoryName}"

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@{
    var recipes = RecipeService.GetRecipesByCategory(CategoryName ?? "");
}

@if (recipes.Count == 0)
{
    <div class="alert alert-info mt-3">
        <p>No recipes found in this category. <a href="submit">Be the first to submit one!</a></p>
    </div>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="text-warning mb-2">★ @recipe.AverageRating.ToString("F1") <span class="text-muted">(@recipe.TotalRatings ratings)</span></p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"

@inject RecipeService RecipeService

@{
    var recipe = RecipeService.GetRecipeById(Id);
}

<PageTitle>@(recipe?.Title ?? "Recipe Not Found") - RecipeHub</PageTitle>

@if (recipe == null)
{
    <div class="alert alert-warning mt-3">
        <h4>Recipe not found</h4>
        <p>The recipe you're looking for doesn't exist. <a href="/">Browse all categories</a></p>
    </div>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <p class="lead mt-2">@recipe.Description</p>

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3 class="mt-4">Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <h3 class="mt-4">Rate this Recipe</h3>
    <StarRating RecipeId="Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }
}

@page "/submit"
@rendermode InteractiveServer

@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted successfully!</h4>
        <p>Your recipe "<strong>@_submittedTitle</strong>" has been added.</p>
        <a href="recipe/@_submittedId" class="btn btn-primary">View Your Recipe</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
                <div class="mb-3">
                    <label for="title" class="form-label">Title <span class="text-danger">*</span></label>
                    <InputText id="title" class="form-control" @bind-Value="_model.Title" />
                    @if (_errors.ContainsKey("Title"))
                    {
                        <div class="text-danger">@_errors["Title"]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                        <option value="">-- Select or type below --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat">@cat</option>
                        }
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="newCategory" class="form-label">Or enter a new category</label>
                    <InputText id="newCategory" class="form-control" @bind-Value="_model.NewCategory" placeholder="e.g., Appetizers" />
                </div>

                <div class="mb-3">
                    <label for="description" class="form-label">Description</label>
                    <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="3" />
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients <span class="text-danger">*</span> (one per line)</label>
                    <InputTextArea id="ingredients" class="form-control" @bind-Value="_model.IngredientsText" rows="6" placeholder="1 cup flour&#10;2 eggs&#10;1 cup sugar" />
                    @if (_errors.ContainsKey("Ingredients"))
                    {
                        <div class="text-danger">@_errors["Ingredients"]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps <span class="text-danger">*</span> (one per line)</label>
                    <InputTextArea id="steps" class="form-control" @bind-Value="_model.StepsText" rows="6" placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
                    @if (_errors.ContainsKey("Steps"))
                    {
                        <div class="text-danger">@_errors["Steps"]</div>
                    }
                </div>

                <button type="submit" class="btn btn-primary">Submit Recipe</button>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeFormModel _model = new();
    private Dictionary<string, string> _errors = new();
    private bool _submitted;
    private string _submittedTitle = "";
    private int _submittedId;

    private void HandleSubmit()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(_model.Title))
            _errors["Title"] = "Title is required.";

        var ingredients = ParseLines(_model.IngredientsText);
        if (ingredients.Count == 0)
            _errors["Ingredients"] = "At least one ingredient is required.";

        var steps = ParseLines(_model.StepsText);
        if (steps.Count == 0)
            _errors["Steps"] = "At least one step is required.";

        if (_errors.Count > 0)
            return;

        var category = !string.IsNullOrWhiteSpace(_model.NewCategory)
            ? _model.NewCategory.Trim()
            : !string.IsNullOrWhiteSpace(_model.Category)
                ? _model.Category
                : "Uncategorized";

        var recipe = new Recipe
        {
            Title = _model.Title.Trim(),
            Category = category,
            Description = _model.Description?.Trim() ?? "",
            Ingredients = ingredients,
            Steps = steps
        };

        RecipeService.AddRecipe(recipe);
        _submittedTitle = recipe.Title;
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private List<string> ParseLines(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return new List<string>();

        return text.Split('\n', StringSplitOptions.RemoveEmptyEntries)
                   .Select(l => l.Trim())
                   .Where(l => l.Length > 0)
                   .ToList();
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = "";
        public string Category { get; set; } = "";
        public string NewCategory { get; set; } = "";
        public string Description { get; set; } = "";
        public string IngredientsText { get; set; } = "";
        public string StepsText { get; set; } = "";
    }
}

@rendermode InteractiveServer

@inject RecipeService RecipeService

<div>
    @if (_hasRated)
    {
        <p class="text-success fw-bold">Thanks for rating!</p>
        <p>
            <span style="color: gold; font-size: 1.5rem;">
                @for (int i = 1; i <= 5; i++)
                {
                    var star = i;
                    @(star <= (int)Math.Round(_updatedAverage) ? "★" : "☆")
                }
            </span>
            <span class="ms-2">@_updatedAverage.ToString("F1") avg (@_updatedTotal ratings)</span>
        </p>
    }
    else
    {
        <div style="cursor: pointer; font-size: 1.5rem; color: gold; user-select: none;"
             @onmouseout="() => _hoverStar = 0">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onmouseover="() => _hoverStar = star"
                      @onclick="() => SubmitRating(star)">@(star <= (_hoverStar > 0 ? _hoverStar : 0) ? "★" : "☆")</span>
            }
        </div>

        @{
            var recipe = RecipeService.GetRecipeById(RecipeId);
        }
        @if (recipe != null && recipe.TotalRatings > 0)
        {
            <p class="mt-1 text-muted">Current rating: ★ @recipe.AverageRating.ToString("F1") (@recipe.TotalRatings ratings)</p>
        }
        else
        {
            <p class="mt-1 text-muted">No ratings yet. Be the first!</p>
        }
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _hoverStar;
    private bool _hasRated;
    private double _updatedAverage;
    private int _updatedTotal;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe != null)
        {
            _updatedAverage = recipe.AverageRating;
            _updatedTotal = recipe.TotalRatings;
        }
        _hasRated = true;
    }
}

